import{_ as o,a0 as l,w as p,s as r,I as n,x as e,a1 as a,A as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Linux 和 FreeDOS 之间复制文件 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 和 FreeDOS 之间复制文件 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 和 FreeDOS 之间复制文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 和 FreeDOS 之间复制文件 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210624 Copy files between Linux and FreeDOS","title":"在 Linux 和 FreeDOS 之间复制文件","tag":"202107","desc":""},"relativePath":"202107/20210624 Copy files between Linux and FreeDOS.md","filePath":"[post].md"}'),u={name:"202107/20210624 Copy files between Linux and FreeDOS.md"};function g(m,s,x,f,k,b){const t=l("Link");return p(),r("div",null,[s[29]||(s[29]=n("h1",{id:"在-linux-和-freedos-之间复制文件",tabindex:"-1"},[e("在 Linux 和 FreeDOS 之间复制文件 "),n("a",{class:"header-anchor",href:"#在-linux-和-freedos-之间复制文件","aria-label":"Permalink to “在 Linux 和 FreeDOS 之间复制文件”"},"​")],-1)),s[30]||(s[30]=n("blockquote",null,[n("p",null,"下面是我如何在我的 FreeDOS 虚拟机和 Linux 桌面系统之间传输文件。")],-1)),s[31]||(s[31]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202107/04/181327bfvv3mmzby9z2dpr.jpg",alt:""})],-1)),s[32]||(s[32]=n("p",null,"我运行 Linux 作为我的主要操作系统，我在一个虚拟机中启动 FreeDOS。大多数时候，我使用 QEMU 作为我的 PC 模拟器，但有时我会用 GNOME Boxes（它使用 QEMU 作为后端虚拟机）或用 VirtualBox 运行其他实验。",-1)),n("p",null,[s[1]||(s[1]=e("我喜欢玩经典的 DOS 游戏，有时我也会调出一个最喜欢的 DOS 应用。我在管理信息系统（MIS）课上讲计算机的历史，有时我会用 FreeDOS 和一个传统的 DOS 应用录制一个演示，比如 As-Easy-As（我最喜欢的 DOS 电子表格，曾经作为“共享软件”发布，但现在可以 ",-1)),a(t,{href:"http://www.triusinc.com/forums/viewtopic.php?t=10"},{default:i(()=>[...s[0]||(s[0]=[e("从 TRIUS 公司免费获得",-1)])]),_:1}),s[2]||(s[2]=e("）。",-1))]),s[33]||(s[33]=n("p",null,"但是以这种方式使用 FreeDOS 意味着我需要在我的 FreeDOS 虚拟机和我的 Linux桌 面系统之间传输文件。让我来展示是如何做到这一点的。",-1)),s[34]||(s[34]=n("h3",{id:"用-guestmount-访问镜像",tabindex:"-1"},[e("用 guestmount 访问镜像 "),n("a",{class:"header-anchor",href:"#用-guestmount-访问镜像","aria-label":"Permalink to “用 guestmount 访问镜像”"},"​")],-1)),n("p",null,[s[4]||(s[4]=e("我曾经通过计算第一个 DOS 分区的偏移量来访问我的虚拟磁盘镜像，然后用正确的选项组合来调用 Linux 的 ",-1)),s[5]||(s[5]=n("code",null,"mount",-1)),s[6]||(s[6]=e(" 命令来匹配这个偏移量。这总是很容易出错，而且不是很灵活。幸运的是，有一个更简单的方法可以做到这一点。来自 ",-1)),a(t,{href:"https://libguestfs.org/"},{default:i(()=>[...s[3]||(s[3]=[e("libguestfs-tools",-1)])]),_:1}),s[7]||(s[7]=e(" 包的 ",-1)),s[8]||(s[8]=n("code",null,"guestmount",-1)),s[9]||(s[9]=e(" 程序可以让你从 Linux 中访问或 ",-1)),s[10]||(s[10]=n("em",null,"挂载",-1)),s[11]||(s[11]=e(" 虚拟磁盘镜像。你可以在 Fedora 上用这个命令安装 ",-1)),s[12]||(s[12]=n("code",null,"libguestfs-tools",-1)),s[13]||(s[13]=e("：",-1))]),s[35]||(s[35]=d(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yum install libguestfs-tools libguestfs</span></span></code></pre></div><p>使用 <code>guestmount</code> 并不像从 GNOME 文件管理器中双击文件那么简单，但命令行的使用并不难。<code>guestmount</code> 的基本用法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ guestmount -a image -m device mountpoint</span></span></code></pre></div><p>在这个用法中，<code>image</code> 是要使用的虚拟磁盘镜像。在我的系统中，我用 <code>qemu-img</code> 命令创建了 QEMU 虚拟磁盘镜像。<code>guestmount</code> 程序可以读取这种磁盘镜像格式，以及 GNOME Boxes 使用的 QCOW2 镜像格式，或者 VirtualBox 使用的 VDI 镜像格式。</p><p><code>device</code> 选项表示虚拟磁盘上的分区。想象一下，把这个虚拟磁盘当作一个真正的硬盘使用。你可以用 <code>/dev/sda1</code> 访问第一个分区，用 <code>/dev/sda2</code> 访问第二个分区，以此类推。这就是 <code>guestmount</code> 的语法。默认情况下，FreeDOS 1.3 RC4 在一个空的驱动器上创建了一个分区，所以访问这个分区的时候要用 <code>/dev/sda1</code>。</p><p>而 <code>mountpoint</code> 是在你的本地 Linux 系统上“挂载” DOS 文件系统的位置。我通常会创建一个临时目录来工作。你只在访问虚拟磁盘时需要挂载点。</p><p>综上所述，我使用这组命令从 Linux 访问我的 FreeDOS 虚拟磁盘镜像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir /tmp/freedos</span></span>
<span class="line"><span>$ guestmount -a freedos.img -m /dev/sda1 /tmp/freedos</span></span></code></pre></div><p>之后，我可以通过 <code>/tmp/freedos</code> 目录访问我的 FreeDOS 文件，使用 Linux 上的普通工具。我可以在命令行中使用 <code>ls /tmp/freedos</code>，或者使用桌面文件管理器打开 <code>/tmp/freedos</code> 挂载点。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /tmp/freedos</span></span>
<span class="line"><span>total 216</span></span>
<span class="line"><span>drwxr-xr-x. 5 root root 8192 May 10 15:53 APPS</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root 85048 Apr 30 07:54 COMMAND.COM</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root  103 May 13 15:48 CONFIG.SYS</span></span>
<span class="line"><span>drwxr-xr-x. 5 root root 8192 May 15 16:52 DEVEL</span></span>
<span class="line"><span>drwxr-xr-x. 2 root root 8192 May 15 13:36 EDLIN</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root 1821 May 10 15:57 FDAUTO.BAT</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root  740 May 13 15:47 FDCONFIG.SYS</span></span>
<span class="line"><span>drwxr-xr-x. 10 root root 8192 May 10 15:49 FDOS</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root 46685 Apr 30 07:54 KERNEL.SYS</span></span>
<span class="line"><span>drwxr-xr-x. 2 root root 8192 May 10 15:57 SRC</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root 3190 May 16 08:34 SRC.ZIP</span></span>
<span class="line"><span>drwxr-xr-x. 3 root root 8192 May 11 18:33 TEMP</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/gnome-file-manager.png" alt="GNOME file manager" title="Using GNOME file manager to access the virtual disk"></p><p><em>使用 GNOME 文件管理器来访问虚拟磁盘</em></p><p>例如，要从我的 Linux <code>projects</code> 目录中复制几个 C 源文件到虚拟磁盘镜像上的 <code>C:\\SRC</code>，以便我以后能在 FreeDOS 下使用这些文件，我可以使用 Linux <code>cp</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp /home/jhall/projects/*.c /tmp/freedos/SRC</span></span></code></pre></div><p>虚拟驱动器上的文件和目录在技术上是不分大小写的，所以你可以用大写或小写字母来引用它们。然而，我发现使用所有大写字母来输入 DOS 文件和目录更为自然。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /tmp/freedos</span></span>
<span class="line"><span>APPS     CONFIG.SYS EDLIN    FDCONFIG.SYS KERNEL.SYS SRC.ZIP</span></span>
<span class="line"><span>COMMAND.COM DEVEL    FDAUTO.BAT FDOS     SRC     TEMP</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls /tmp/freedos/EDLIN</span></span>
<span class="line"><span>EDLIN.EXE MAKEFILE.OW</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls /tmp/freedos/edlin</span></span>
<span class="line"><span>EDLIN.EXE MAKEFILE.OW</span></span></code></pre></div><h3 id="用-guestmount-卸载" tabindex="-1">用 guestmount 卸载 <a class="header-anchor" href="#用-guestmount-卸载" aria-label="Permalink to “用 guestmount 卸载”">​</a></h3><p>在你再次在虚拟机中使用虚拟磁盘镜像之前，你应该总是先 <em>卸载</em>。如果你在运行 QEMU 或 VirtualBox 时让镜像挂载，你有可能弄乱你的文件。</p><p>与 <code>guestmount</code> 配套的命令是 <code>guestunmount</code>，用来卸载磁盘镜像。只要给出你想卸载的挂载点就可以了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ guestunmount /tmp/freedos</span></span></code></pre></div><p>请注意命令拼写与 Linux 的 <code>umount</code> 稍有不同。</p><hr>`,22)),n("p",null,[s[15]||(s[15]=e("via: ",-1)),a(t,{href:"https://opensource.com/article/21/6/copy-files-linux-freedos"},{default:i(()=>[...s[14]||(s[14]=[e("https://opensource.com/article/21/6/copy-files-linux-freedos",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=e("作者：",-1)),a(t,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[16]||(s[16]=[e("Jim Hall",-1)])]),_:1}),s[21]||(s[21]=e(" 选题：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[17]||(s[17]=[e("lujun9972",-1)])]),_:1}),s[22]||(s[22]=e(" 译者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:i(()=>[...s[18]||(s[18]=[e("geekpi",-1)])]),_:1}),s[23]||(s[23]=e(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[19]||(s[19]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[26]||(s[26]=e("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[24]||(s[24]=[e("LCTT",-1)])]),_:1}),s[27]||(s[27]=e(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...s[25]||(s[25]=[e("Linux中国",-1)])]),_:1}),s[28]||(s[28]=e(" 荣誉推出",-1))])])}const D=o(u,[["render",g]]);export{C as __pageData,D as default};
